{"backendPid":147,"connection":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":9,"sql":"CREATE FUNCTION \"model_c55a163c75ee45df\".\"before\"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE k bigint; p uuid; live boolean; v uuid; BEGIN\nIF TG_OP<>'DELETE' AND (NEW.id IS NULL OR NEW.balance IS NULL OR NEW.active IS NULL OR NEW.region IS NULL) THEN RETURN NEW; END IF;\nIF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'primary key mutation'; END IF;\nk:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;\nSELECT version,present INTO p,live FROM \"model_c55a163c75ee45df\".\"state\" WHERE key=k FOR UPDATE;\nIF NOT FOUND THEN RAISE EXCEPTION 'key outside configured domain'; END IF;\nIF TG_OP<>'INSERT' AND (NOT live OR p IS DISTINCT FROM OLD.version) THEN RAISE EXCEPTION 'source mismatch'; END IF;\nv:=gen_random_uuid();\nINSERT INTO \"model_c55a163c75ee45df\".\"candidates\" VALUES(v,k,p,TG_OP,live,TG_OP<>'DELETE',CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END);\nIF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW.version:=v; RETURN NEW; END IF;\nEND$model$","transaction":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":147,"connection":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":10,"sql":"CREATE FUNCTION \"model_c55a163c75ee45df\".\"after\"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE v uuid; c record; n integer; BEGIN\nv:=CASE WHEN TG_OP='DELETE' THEN \"model_c55a163c75ee45df\".\"delete_token\"(OLD.id,OLD.version) ELSE NEW.version END;\nSELECT * INTO c FROM \"model_c55a163c75ee45df\".\"candidates\" WHERE version=v;\nIF NOT FOUND OR c.action<>TG_OP OR c.key IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END) OR c.image IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END) THEN RAISE EXCEPTION 'actual effect mismatch'; END IF;\nIF TG_OP='INSERT' AND c.old_present THEN RAISE EXCEPTION 'insert presence mismatch'; END IF;\nUPDATE \"model_c55a163c75ee45df\".\"state\" SET version=v,present=(TG_OP<>'DELETE') WHERE key=c.key AND version IS NOT DISTINCT FROM c.predecessor AND present=c.old_present;\nGET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'effect state mismatch'; END IF;\nINSERT INTO \"model_c55a163c75ee45df\".\"effects\" SELECT * FROM \"model_c55a163c75ee45df\".\"candidates\" WHERE version=v;\nIF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND$model$","transaction":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":147,"connection":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":11,"sql":"CREATE FUNCTION \"model_c55a163c75ee45df\".\"predecessor\"(v uuid) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE n integer; p uuid; BEGIN SELECT count(*),min(predecessor::text)::uuid INTO n,p FROM \"model_c55a163c75ee45df\".\"candidates\" WHERE version=v; IF n<>1 THEN RAISE EXCEPTION 'predecessor not unique'; END IF; RETURN p; END$model$","transaction":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":147,"connection":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":12,"sql":"CREATE FUNCTION \"model_c55a163c75ee45df\".\"delete_token\"(k bigint,p uuid) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE n integer; v uuid; BEGIN SELECT count(*),min(version::text)::uuid INTO n,v FROM \"model_c55a163c75ee45df\".\"candidates\" WHERE key=k AND predecessor=p AND action='DELETE'; IF n<>1 THEN RAISE EXCEPTION 'delete not unique'; END IF; RETURN v; END$model$","transaction":"setup-7d4e983fd15946bd94b1d4d33c0a1cd2-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
